function ECSSystem:IsAllCompExists(componentNames, entity)
    if isTable(componentNames) then
        return
    end
    local ret = true
    for i = 1, componentNames do
        if not entity:IsCompExists(componentNames[i]) then
            ret = false
            break
        end
    end
    return ret
end

