        self.__isGetHashCode = true
        self.__filterNameHashCode = self.world.group:StringArrayToInt(self:GetFilter())
    end
    return self.world.group:GetEntityByFilter(self.__filterNameHashCode, self:GetFilter())
end

---GetEntityList
